<?php $snapshot=$report['success'];$data=$snapshot['data'];$periods=$data['periods']; ?>
<p class="readiness-stamp">Saved <?=e($snapshot['completed_at'])?> UTC. Current: <?=e($periods['start'])?>–<?=e($periods['end'])?>; previous: <?=e($periods['previous_start'])?>–<?=e($periods['previous_end'])?>. Dates use America/Los_Angeles.</p>
<div class="readiness-table-wrap"><table><caption>Property totals, requested separately from query rows</caption><thead><tr><th scope="col">Metric</th><th scope="col">Current period</th><th scope="col">Previous period</th><th scope="col">Change</th></tr></thead><tbody>
<?php foreach(['clicks'=>'Clicks','impressions'=>'Impressions','ctr'=>'Click-through rate','position'=>'Average position']as$key=>$label):?><?php $current=$data['totals']['current'][$key]??null;$previous=$data['totals']['previous'][$key]??null;$multiplier=$key==='ctr'?100:1;$precision=in_array($key,['ctr','position'],true)?2:0;?><tr><th scope="row"><?=e($label)?></th><td><?=$current===null?'Not returned':number_format($current*$multiplier,$precision).($key==='ctr'?'%':'')?></td><td><?=$previous===null?'Not returned':number_format($previous*$multiplier,$precision).($key==='ctr'?'%':'')?></td><td><?php if($current===null || $previous===null):?>Not available<?php else:?><?=($current-$previous>=0?'+':'').number_format(($current-$previous)*$multiplier,$precision).($key==='ctr'?' percentage points':'')?><?php endif;?></td></tr><?php endforeach;?>
</tbody></table></div><p class="readiness-small">Lower average position usually means a higher search position. Missing data is shown as “Not returned”, not zero. These are observed search metrics; they do not establish that a particular campaign caused a change.</p>
<?php foreach(['query'=>'Queries','country'=>'Countries and territories (provider ISO codes)','device'=>'Devices']as$dimension=>$label):?><details <?=$dimension==='query'?'open':''?>><summary><?=e($label)?></summary><p class="readiness-small">Up to <?=intval($data['row_limits'][$dimension]??$data['row_limit']??100)?> top returned rows in each period. Search Console limits and anonymized queries mean this is not a complete list. A row absent from one period may fall outside the returned set; it is not treated as zero.</p><div class="readiness-table-wrap"><table><thead><tr><th scope="col"><?=e($label)?></th><th scope="col">Current clicks</th><th scope="col">Previous clicks</th><th scope="col">Current impressions</th><th scope="col">Previous impressions</th><th scope="col">Current CTR</th><th scope="col">Current position</th></tr></thead><tbody>
<?php foreach($data['dimensions'][$dimension]??[] as $row):?><tr><th scope="row"><?=e($row['key'])?></th><td><?=$row['current']===null?'Not returned':number_format($row['current']['clicks'])?></td><td><?=$row['previous']===null?'Not returned':number_format($row['previous']['clicks'])?></td><td><?=$row['current']===null?'Not returned':number_format($row['current']['impressions'])?></td><td><?=$row['previous']===null?'Not returned':number_format($row['previous']['impressions'])?></td><td><?=$row['current']===null?'Not returned':number_format($row['current']['ctr']*100,2).'%'?></td><td><?=$row['current']===null?'Not returned':number_format($row['current']['position'],2)?></td></tr><?php endforeach;?>
<?php if(empty($data['dimensions'][$dimension])):?><tr><td colspan="7">No rows were returned for either period.</td></tr><?php endif;?></tbody></table></div></details><?php endforeach;?>
